import * as THREE from 'three';
import {refineSurfaceMaterials100} from './visual-quality100.js?v=194';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
export const SR_PARTS126=[
 ['mt','01 · Celdas de media tensión','Recepción y seccionamiento de CA','Tres celdas abiertas muestran barras trifásicas, aisladores, seccionamiento, interruptor, transformadores de medida y relés. Su disposición es didáctica; no constituye un plano de una instalación.'],
 ['transformer','02 · Transformador de tracción','Transformador seco · doble secundario','Núcleo laminado, tres columnas bobinadas, primario y dos secundarios con salidas diferenciadas. METRO.pdf, páginas 14–16, describe 15 kV / 540 V CA, doble secundario y refrigeración forzada. Son valores de esa referencia histórica, no una verificación de todas las unidades actuales.'],
 ['rectifier','03 · Rectificador y reactor','Dos puentes de seis pulsos · doce diodos','Bastidor con doce diodos, disipadores, fusibles, sensores, barras y ventilación. Los dos puentes se representan con una bobina de equilibrio. Convierte la alimentación alterna en continua de tracción; el esquema documental indica 750 V CD.'],
 ['dc','04 · Distribución de tracción','Interruptores y alimentadores de CD','Celdas con interruptores de corriente continua, seccionadores, aisladores, barras y medición. CD+ es la alimentación; CD− identifica el retorno de tracción. No representa una red de +750 y −750 V ni se une aquí al conductor de protección PE.'],
 ['control','05 · Control y protección','PLC / RTU · relés · comunicaciones','Carriles DIN con protecciones, fuentes, módulos de entradas y salidas, borneras y canaletas; panel de supervisión y comunicaciones. El cableado de control se distingue del de potencia.'],
 ['battery','06 · Baterías y cargador','Alimentación auxiliar de control','Banco de celdas en dos niveles con puentes, terminales, protección y cargador independiente. Se omiten tensiones, autonomía y química sin confirmación documental.'],
 ['aux','07 · Servicios auxiliares','Alumbrado y ventilación del local','Transformador auxiliar, tablero de servicios, tomas e iluminación. Estos servicios locales no convierten una SAF en una subestación rectificadora de tracción.'],
 ['cables','08 · Canalizaciones','Potencia y control separados','Bandejas con peldaños, soportes, cables trifásicos, salidas de continua y canal de control. La tapa parcial permite ver el tendido. Recorrido ilustrativo sin dimensionado constructivo.'],
 ['earth','09 · Puesta a tierra','Barra PE y enlaces de protección','Barra de protección, enlaces a envolventes y registro de electrodo. El retorno CD− de tracción se mantiene separado de PE en este modelo; no se presupone su conexión eléctrica.'],
 ['civil','10 · Obra civil','Bancadas y acceso de servicio','Losa, zócalos, bancadas y paredes de hormigón con puerta de acceso. Interior visible mediante corte de paredes, sin atribuir esta planta a una estación concreta.'],
 ['roof','11 · Cubierta y ventilación','Extracción y entradas de aire','Cubierta, rejillas y extractores sobre el local. La vista Interior retira la cubierta y los cerramientos delanteros para inspeccionar los equipos.'],
 ['fire','12 · Protección contra incendios','Detección · alarma · extinción','Detectores, pulsador, sirena, central y extintores accesibles. Su representación es visual y no acredita un proyecto contra incendios ni un procedimiento operativo.']
].map(([id,title,subtitle,description])=>({id,title,subtitle,description}));
export function createRectifier126({batchGeometry=true,finishes=true}={}){
 const root=new THREE.Group();root.name='SR_Interior_didactico126';root.userData={kind:'SR',illustrative:true,source:'METRO.pdf pp.14–16 + despieces aportados',primaryType:'dry',secondaryCount:2,diodeCount:12,tractionReturnBondedToPE:false};
 const parts=new Map(),materials={};
 const palette={steel:['#8a969d',.7,.35],paint:['#768d91',.25,.48],dark:['#202c34',.2,.65],copper:['#b97342',.8,.3],insulator:['#713e31',.08,.42],coil:['#c18b55',.65,.4],core:['#555f68',.78,.48],white:['#d5ded9',.05,.65],black:['#172028',0,.85],red:['#b94236',.1,.55],blue:['#416a9c',.1,.5],yellow:['#d8bb51',.1,.65],green:['#488a61',.1,.6],concrete:['#7b817f',0,.92],floor:['#59615f',0,.86],screen:['#78c5bd',.1,.3]};
 for(const[k,[color,metalness,roughness]]of Object.entries(palette))materials[k]=new THREE.MeshStandardMaterial({name:'SR126 '+({concrete:'Concreto',floor:'Piso',steel:'Acero cepillado',paint:'Pintura',dark:'Panel grafito',white:'Panel marfil',black:'Goma',core:'Fundicion',coil:'Cobre',screen:'Pantalla',insulator:'Aislante',red:'Pintura roja',blue:'Pintura azul',green:'Pintura verde',yellow:'Pintura amarilla',copper:'Cobre'}[k]||k),color,metalness,roughness,...(k==='screen'?{emissive:color,emissiveIntensity:.3}:{})});
 for(const p of SR_PARTS126){const g=new THREE.Group();g.name=p.id;g.userData={...p,partId:p.id,detailCounts:{}};parts.set(p.id,g);root.add(g);}
 function mesh(g,name,geo,pos,mat,rot){const m=new THREE.Mesh(geo,materials[mat]);m.name=name;m.position.set(...pos);if(rot)m.rotation.set(...rot);g.add(m);g.userData.detailCounts??={};g.userData.detailCounts[name]=(g.userData.detailCounts[name]||0)+1;return m;}
 const box=(g,n,x,y,z,w,h,d,m='steel')=>mesh(g,n,new THREE.BoxGeometry(w,h,d),[x,y,z],m);
 const cyl=(g,n,x,y,z,r,h,m='steel',rot)=>mesh(g,n,new THREE.CylinderGeometry(r,r,h,12),[x,y,z],m,rot);
 function wire(g,n,pts,r,mat){const points=pts.map(p=>new THREE.Vector3(...p));for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],v=b.clone().sub(a),m=mesh(g,n,new THREE.CylinderGeometry(r,r,v.length(),8),a.clone().add(b).multiplyScalar(.5).toArray(),mat);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.normalize());}}
 function cabinet(g,x,z,w=1,h=2.4){box(g,'Gabinete_base',x,.2,z,w,.16,.9,'dark');box(g,'Gabinete_fondo',x,h/2+.2,z+.43,w,h,.07,'paint');for(const a of[-1,1]){box(g,'Gabinete_lateral',x+a*(w/2-.025),h/2+.2,z,.05,h,.9,'paint');box(g,'Montante',x+a*(w/2-.12),h/2+.2,z-.32,.045,h,.045);}box(g,'Gabinete_techo',x,h+.2,z,w,.06,.9);box(g,'Umbral_abierto',x,.38,z-.43,w,.28,.06,'paint');}
 function din(g,x,y,z,n=5){box(g,'Carril_DIN',x,y,z,.75,.045,.045);for(let i=0;i<n;i++){box(g,'Modulo_DIN',x-.32+i*.14,y,z-.065,.11,.22,.12,'white');box(g,'Contacto_modulo',x-.32+i*.14,y+.07,z-.14,.035,.045,.025,'dark');}}
 function isolator(g,x,y,z){for(let i=0;i<4;i++)cyl(g,'Aislador',x,y+i*.035,z,.065,.025,'insulator');}
 // MT: each cell has exposed bus, insulated poles and measuring/protection apparatus.
 const mt=parts.get('mt');for(let c=0;c<3;c++){let x=-6.3+c*1.12;cabinet(mt,x,2,1.02,2.65);for(let p=0;p<3;p++){let px=x-.27+p*.27;isolator(mt,px,2.32,1.9);box(mt,'Barra_MT',px,2.5,1.9,.075,.065,.64,'copper');cyl(mt,'Polo_interruptor',px,1.2,2,.09,.65,'insulator');wire(mt,'Conexion_MT',[[px,2.35,1.9],[px,1.55,1.9]],.025,'copper');box(mt,'Seccionador',px,1.95,1.85,.04,.25,.05,'steel');cyl(mt,'Transformador_medida',px,.65,1.96,.12,.16,'dark');}box(mt,'Mecanismo_interruptor',x,.9,1.7,.72,.22,.22,'dark');din(mt,x,2.68,1.58,4);}
 const tr=parts.get('transformer'),tx=-1.85;box(tr,'Bancada_transformador',tx,.23,2,2.5,.3,1.8,'concrete');for(const y of[.55,2.14])box(tr,'Yugo_nucleo',tx,y,2,2.2,.24,.68,'core');
 for(let p=0;p<3;p++){let x=tx-.73+p*.73;box(tr,'Columna_nucleo',x,1.34,2,.27,1.5,.46,'core');cyl(tr,'Bobina_primaria',x,1.3,2,.31,1.22,'insulator');for(let s=0;s<2;s++){cyl(tr,'Bobina_secundaria_'+s,x,1.0+s*.55,2,.34,.43,'coil');for(let k=0;k<8;k++)cyl(tr,'Espira_bobina',x,.81+s*.55+k*.05,2,.35,.014,'copper');wire(tr,'Salida_secundario_'+s,[[x,1.03+s*.55,1.7],[x,1.03+s*.55,1.05+p*.16],[tx+1.2,1.03+s*.55,1.05+p*.16]],.022,s?'blue':'red');}isolator(tr,x,2.3,2);box(tr,'Pletina_primario',x,2.55,2,.055,.28,.055,'copper');}
 for(const x of[tx-.9,tx+.9]){box(tr,'Mordaza_nucleo',x,1.32,2.42,.09,1.85,.07);cyl(tr,'Ventilador_transformador',x,.51,1.24,.17,.1,'dark',[Math.PI/2,0,0]);}for(let i=0;i<9;i++)box(tr,'Laminacion_nucleo',tx,2.15,1.65+i*.08,2.18,.015,.008,'steel');
 const rec=parts.get('rectifier');cabinet(rec,1.15,2,1.8,2.7);for(let bridge=0;bridge<2;bridge++){let x=.72+bridge*.86;for(let d=0;d<6;d++){let y=.63+d*.3;box(rec,'Disipador',x,y,1.96,.61,.2,.28,'core');for(let f=0;f<6;f++)box(rec,'Aleta_disipador',x-.25+f*.1,y,1.76,.025,.19,.22);cyl(rec,'Diodo_potencia',x,y,1.58,.072,.09,'white',[Math.PI/2,0,0]);box(rec,'Fusible_diodo',x+.23,y,1.55,.075,.15,.06,'white');box(rec,'Conexion_diodo',x,y+.1,1.58,.08,.08,.04,'copper');}box(rec,'Barra_puente',x-.32,1.36,1.65,.055,1.9,.055,'copper');box(rec,'Sensor_temperatura',x,2.42,1.68,.1,.1,.06,'yellow');cyl(rec,'Ventilador_rectificador',x,2.72,2,.19,.09,'dark');}
 box(rec,'Nucleo_reactor_equilibrio',1.15,.5,.95,.62,.45,.3,'core');for(let i=0;i<12;i++)box(rec,'Espira_reactor',.86+i*.052,.51,.95,.024,.49,.36,'copper');
 const dc=parts.get('dc');for(let c=0;c<2;c++){let x=3.7+c*1.15;cabinet(dc,x,2,1.05,2.65);for(const [k,m]of[[0,'red'],[1,'blue']]){box(dc,'Barra_CD_'+(k?'retorno':'positivo'),x-.3+k*.6,1.65,2.15,.07,1.8,.06,'copper');box(dc,'Identificador_'+m,x-.3+k*.6,2.5,2.1,.1,.08,.06,m);for(const y of[.7,2.3])isolator(dc,x-.3+k*.6,y,2.15);}box(dc,'Interruptor_ultrarrapido_CD',x,1.25,1.9,.7,.6,.42,'dark');box(dc,'Camara_extincion_CD',x,1.75,1.9,.65,.3,.4,'core');box(dc,'Mecanismo_disparo',x,1.12,1.62,.18,.2,.12,'red');for(const dx of[-.22,.22]){isolator(dc,x+dx,2.04,1.85);box(dc,'Seccionador_CD',x+dx,2.26,1.85,.035,.22,.055,'copper');}box(dc,'Medidor_CD',x,2.5,1.6,.26,.18,.05,'screen');}
 const ctrl=parts.get('control');cabinet(ctrl,6.25,2,1.15,2.6);for(let row=0;row<5;row++)din(ctrl,6.25,.7+row*.36,1.92,5);for(const x of[5.79,6.71]){box(ctrl,'Canaleta_control',x,1.5,1.88,.085,1.9,.09,'white');for(let i=0;i<16;i++)box(ctrl,'Ranura_canaleta',x,.65+i*.11,1.82,.06,.012,.015,'dark');}box(ctrl,'PLC_RTU',6.25,1.78,1.72,.54,.25,.19,'dark');for(let i=0;i<6;i++)box(ctrl,'LED_PLC',6.05+i*.07,1.86,1.61,.023,.023,.018,'screen');box(ctrl,'Fuente_control',6.25,.5,1.77,.46,.2,.22,'steel');box(ctrl,'Switch_comunicaciones',6.25,2.14,1.72,.54,.16,.16,'dark');for(let i=0;i<6;i++)box(ctrl,'Puerto_comunicaciones',6.05+i*.07,2.14,1.62,.05,.055,.025,'white');box(ctrl,'Pantalla_SCADA',6.25,2.53,1.58,.58,.26,.07,'dark');box(ctrl,'Display_SCADA',6.25,2.53,1.535,.5,.18,.02,'screen');
 const bat=parts.get('battery');for(const y of[.35,1.05]){box(bat,'Estante_bateria',5.6,y,-1.7,2.2,.065,.75);for(let i=0;i<8;i++){let x=4.67+i*.27;box(bat,'Celda_bateria',x,y+.25,-1.7,.23,.44,.48,'dark');for(const dz of[-.13,.13])cyl(bat,'Borne_bateria',x,y+.49,-1.7+dz,.025,.055,dz<0?'red':'blue');if(i<7)box(bat,'Puente_bateria',x+.135,y+.52,-1.83,.27,.03,.04,'copper');}}for(const x of[4.45,6.75])box(bat,'Pata_bastidor',x,.8,-1.7,.06,1.6,.75);cabinet(bat,7,-2,.65,1.6);din(bat,7,1.2,-2.1,3);box(bat,'Cargador',7,.65,-2.1,.44,.4,.25,'dark');
 const aux=parts.get('aux');cabinet(aux,-6,-2,1.3,1.8);din(aux,-6,1.5,-2.1,6);box(aux,'Transformador_auxiliar',-6,.75,-2,.7,.65,.5,'core');for(let i=0;i<3;i++)cyl(aux,'Bobina_auxiliar',-6.23+i*.23,.75,-2,.12,.52,'coil');for(const x of[-5,0,5]){box(aux,'Luminaria',x,3.55,-.6,1.2,.07,.17,'white');box(aux,'Difusor_LED',x,3.5,-.6,1.1,.025,.12,'screen');}box(aux,'Toma_servicio',-7.72,.85,-2,.06,.18,.15,'white');
 const cab=parts.get('cables');
 for(let p=0;p<3;p++){const x=-1.85-.73+p*.73,z=1.05+p*.16;wire(cab,'Acometida_primaria',[[-4.05+p*.14,2.55,2.1],[-4.05+p*.14,3,2.1],[x,3,2],[x,2.7,2]],.026,['red','yellow','blue'][p]);for(let s=0;s<2;s++)wire(cab,'Entrada_CA_puente_'+s,[[-.65,1.03+s*.55,z],[.25+s*.04,1.03+s*.55,z],[.25+s*.04,2.5+p*.07,z],[.72+s*.86,2.5+p*.07,z]],.018,s?'blue':'red');}
 wire(cab,'Salida_rectificador_positivo',[[1.95,2.55,1.7],[2.5,2.55,1.7],[2.5,2.9,2.1],[3.4,2.9,2.1],[3.4,2.5,2.1]],.035,'red');wire(cab,'Retorno_traccion_CD',[[4,2.5,2.1],[4,2.95,2.3],[2.35,2.95,2.3],[2.35,.7,1],[1.5,.7,1]],.035,'blue');
 for(const z of[.8,3.4]){for(const dx of[-.32,.32])box(cab,'Larguero_bandeja',0,3.2,z+dx,14,.08,.035);for(let x=-6.8;x<7;x+=.32)box(cab,'Peldano_bandeja',x,3.17,z,.04,.035,.64);for(let p=0;p<3;p++)wire(cab,'Cable_CA',[[ -6.4,3.26,z-.2+p*.18],[1.2,3.26,z-.2+p*.18]],.034,['red','yellow','blue'][p]);for(let x=-6;x<=6;x+=3)box(cab,'Soporte_bandeja',x,3.45,z,.045,.55,.045);}
 for(const [x,color]of[[3.6,'red'],[3.85,'blue']])wire(cab,'Cable_CD',[[x,2.7,2.2],[x,3.0,2.2],[x,3,3.4],[7.5,3,3.4]],.045,color);wire(cab,'Cable_control',[[6.4,.4,2],[6.4,.18,2],[6.4,.18,-1],[0,.18,-1]],.022,'black');for(let x=-3;x<4;x+=.5)box(cab,'Tapa_registro_parcial',x,.11,-1.6,.47,.045,.65,'steel');
 const earth=parts.get('earth');box(earth,'Barra_PE',0,.25,-3.4,2.4,.1,.055,'copper');for(let x=-1;x<=1;x+=.25)cyl(earth,'Terminal_PE',x,.25,-3.45,.025,.05,'steel',[Math.PI/2,0,0]);wire(earth,'Conductor_PE',[[-7,.16,3.8],[7,.16,3.8],[7,.16,-3.4],[0,.16,-3.4]],.022,'green');for(let x=-6;x<=6;x+=2)wire(earth,'Enlace_equipotencial',[[x,.16,3.8],[x,.16,2.4],[x,.36,2.4]],.018,'green');box(earth,'Registro_electrodo',-2,.13,-3.4,.45,.08,.45,'dark');cyl(earth,'Electrodo_ilustrativo',-2,-.35,-3.4,.025,.8,'copper');
 const civil=parts.get('civil');box(civil,'Losa',0,-.08,0,16,.25,10,'floor');box(civil,'Muro_posterior',0,1.95,4.9,16,4,.2,'concrete');const cut=new THREE.Group();cut.name='Cerramiento_retirado';civil.add(cut);for(const x of[-7.9,7.9])box(cut,'Muro_lateral',x,1.95,0,.2,4,10,'concrete');box(cut,'Muro_frente',-1.2,1.95,-4.9,13.6,4,.2,'concrete');box(cut,'Puerta_acceso',6.65,1.2,-4.91,1.5,2.45,.08,'paint');root.userData.frontWall=cut;
 const roof=parts.get('roof');box(roof,'Cubierta',0,4.02,0,16,.18,10,'concrete');for(const x of[-4,4]){box(roof,'Conducto_extractor',x,4.25,2,.9,.5,.8,'steel');cyl(roof,'Extractor',x,4.53,2,.33,.08,'dark');for(let k=0;k<8;k++)box(roof,'Rejilla_extraccion',x-.32+k*.09,4.6,2,.025,.025,.7);}for(let k=0;k<10;k++)box(roof,'Rejilla_entrada',-7.76,2.5,-2+k*.14,.06,.55,.055,'dark');
 const fire=parts.get('fire');for(const x of[-7,7]){cyl(fire,'Extintor',x,.65,-3.8,.12,.75,'red');box(fire,'Manija_extintor',x,1.07,-3.8,.15,.065,.09,'dark');box(fire,'Soporte_extintor',x,.9,-3.96,.24,.4,.05,'white');}for(const x of[-5,0,5])cyl(fire,'Detector_incendio',x,3.65,.3,.11,.07,'white');box(fire,'Central_incendio',7.72,1.6,-3,.1,.5,.4,'red');box(fire,'Pulsador_alarma',7.72,1.1,-3.8,.1,.14,.14,'red');box(fire,'Sirena',7.72,2.4,-3,.1,.25,.2,'red');
 if(finishes)refineSurfaceMaterials100(root,4);root.updateMatrixWorld(true);
 // Batch opaque geometry within each selectable assembly; front cut remains independently visible.
 function batch(g){const buckets=new Map(),remove=[];g.traverse(o=>{if(!o.isMesh)return;const a=buckets.get(o.material)||[];o.updateMatrix();const geo=o.geometry.clone().applyMatrix4(o.matrix);a.push(geo);buckets.set(o.material,a);remove.push(o);});for(const o of remove){o.parent.remove(o);o.geometry.dispose();}for(const[mat,geos]of buckets){const geo=mergeGeometries(geos);for(const q of geos)q.dispose();const m=new THREE.Mesh(geo,mat);m.name=g.name+'_'+mat.name;g.add(m);}}
 // Civil cut is excluded so Interior can toggle it independently.
 if(batchGeometry){civil.remove(cut);for(const g of parts.values())batch(g);batch(cut);civil.add(cut);}cut.visible=false;roof.visible=false;
 root.userData.parts=parts;root.userData.materials=materials;return root;
}
